$rows=db()->query("SELECT md.*,m.equipo,m.serie_placa,m.anio_equipo,COALESCE(c.name,'Sin empresa') empresa,mdc.nombre documento,COALESCE(u.name,'') registered_by,ob.name observation_by,rb.name resolved_by FROM maquinaria_documentos md JOIN maquinarias m ON m.id=md.maquinaria_id AND m.estado=1 JOIN maquinaria_documentos_catalogo mdc ON mdc.id=md.documento_id LEFT JOIN companies c ON c.id=m.company_id LEFT JOIN users u ON u.id=md.registered_by_user_id LEFT JOIN users ob ON ob.id=md.observation_by_user_id LEFT JOIN users rb ON rb.id=md.observation_resolved_by_user_id ORDER BY m.equipo,m.serie_placa,mdc.nombre")->fetchAll();
