foreach($rows as &$r){$r['status']=status_alert_document_status($r['fecha_fin'],'maquinaria.documentos',(int)$r['documento_id'],true);$k=$r['status']['key'];$counts[$k]++;$types[$r['documento']]=($types[$r['documento']]??0)+1;$typeNames[$r['documento']]=1;$companies[$r['empresa']]=1;$byMachine[$r['maquinaria_id']][$k]++;}unset($r);
ksort($companies);ksort($typeNames);arsort($types);$mc=array_values(array_filter($byMachine,fn($m)=>$m['verde']+$m['amarillo']+$m['rojo']));usort($mc,fn($a,$b)=>(($b['rojo']*100)+$b['amarillo'])<=>(($a['rojo']*100)+$a['amarillo']));$mc=array_slice($mc,0,10);
uksort($equipmentByCompany,static function(string $a,string $b)use($equipmentByCompany):int{$countComparison=$equipmentByCompany[$b]<=>$equipmentByCompany[$a];return $countComparison!==0?$countComparison:strnatcasecmp($a,$b);});$payload=['status'=>array_values($counts),'companies'=>['labels'=>array_keys($equipmentByCompany),'values'=>array_values($equipmentByCompany)]];
$documented=count(array_filter($byMachine,fn($m)=>$m['verde']+$m['amarillo']+$m['rojo']));
/* Detalle paginado en servidor: filtros + COUNT + LIMIT/OFFSET */
$detailFilters=[
 'machine'=>(int)($_GET['machine']??0),'company'=>trim((string)($_GET['company']??'')),
 'document'=>trim((string)($_GET['document']??'')),'state'=>trim((string)($_GET['state']??'')),
 'search'=>trim((string)($_GET['search']??'')),'observation'=>trim((string)($_GET['observation']??'')),
];
$detailPage=max(1,(int)($_GET['page']??1));$detailPerPage=10;
$allowedDocumentIds=array_values(array_unique(array_map('intval',array_column($rows,'documento_id'))));
$detailWhere=['m.estado=1'];$detailParams=[];
if($allowedDocumentIds){$allowedPlaceholders=[];foreach($allowedDocumentIds as $index=>$documentId){$key='allowed_'.$index;$allowedPlaceholders[]=':'.$key;$detailParams[$key]=$documentId;}$detailWhere[]='md.documento_id IN ('.implode(',',$allowedPlaceholders).')';}else{$detailWhere[]='1=0';}
if($detailFilters['machine']>0){$detailWhere[]='md.maquinaria_id=:filter_machine';$detailParams['filter_machine']=$detailFilters['machine'];}
if($detailFilters['company']!==''){$detailWhere[]="COALESCE(c.name,'Sin empresa')=:filter_company";$detailParams['filter_company']=$detailFilters['company'];}
if($detailFilters['document']!==''){$detailWhere[]='mdc.nombre=:filter_document';$detailParams['filter_document']=$detailFilters['document'];}
if($detailFilters['search']!==''){$detailWhere[]='(m.equipo LIKE :search_equipment OR m.serie_placa LIKE :search_series OR mdc.nombre LIKE :search_document)';$searchValue='%'.$detailFilters['search'].'%';$detailParams['search_equipment']=$searchValue;$detailParams['search_series']=$searchValue;$detailParams['search_document']=$searchValue;}
if($detailFilters['observation']==='observed'){$detailWhere[]="md.observation_status='observed'";}elseif($detailFilters['observation']==='approved'){$detailWhere[]="COALESCE(md.observation_status,'none') IN ('none','approved')";}
$statusSql="CASE WHEN md.fecha_fin<CURDATE() THEN 'rojo' WHEN md.fecha_fin<=DATE_ADD(CURDATE(),INTERVAL COALESCE(sas.warning_days,30) DAY) THEN 'amarillo' ELSE 'verde' END";
if(in_array($detailFilters['state'],['verde','amarillo','rojo'],true)){$detailWhere[]=$statusSql.'=:filter_state';$detailParams['filter_state']=$detailFilters['state'];}
$detailFrom=" FROM maquinaria_documentos md JOIN maquinarias m ON m.id=md.maquinaria_id JOIN maquinaria_documentos_catalogo mdc ON mdc.id=md.documento_id LEFT JOIN companies c ON c.id=m.company_id LEFT JOIN users u ON u.id=md.registered_by_user_id LEFT JOIN users ob ON ob.id=md.observation_by_user_id LEFT JOIN users rb ON rb.id=md.observation_resolved_by_user_id LEFT JOIN status_alert_settings sas ON sas.scope_key='maquinaria.documentos' AND sas.catalog_id=md.documento_id WHERE ".implode(' AND ',$detailWhere);
$countStmt=db()->prepare('SELECT COUNT(*)'.$detailFrom);$countStmt->execute($detailParams);$detailTotal=(int)$countStmt->fetchColumn();
$detailTotalPages=max(1,(int)ceil($detailTotal/$detailPerPage));$detailPage=min($detailPage,$detailTotalPages);$detailOffset=($detailPage-1)*$detailPerPage;
$detailStmt=db()->prepare("SELECT md.*,m.equipo,m.serie_placa,m.anio_equipo,COALESCE(c.name,'Sin empresa') empresa,mdc.nombre documento,COALESCE(u.name,'') registered_by,ob.name observation_by,rb.name resolved_by".$detailFrom." ORDER BY m.equipo,m.serie_placa,mdc.nombre LIMIT :detail_limit OFFSET :detail_offset");
