foreach($rows as &$row){$row['status']=status_alert_document_status((string)$row['fecha_fin'],'maquinaria.documentos',(int)$row['documento_id'],true);}unset($row);
$detailFromRecord=$detailTotal?$detailOffset+1:0;$detailToRecord=min($detailOffset+$detailPerPage,$detailTotal);
$detailQuery=$_GET;unset($detailQuery['page']);
$detailPageUrl=static function(int $page)use($detailQuery):string{$query=$detailQuery;$query['page']=$page;return '?'.http_build_query($query).'#detalle-maquinaria';};
