const setPermission=allowed=>{canObserve=allowed===true;observationText.readOnly=!canObserve;observationText.classList.toggle('observation-input-locked',!canObserve);observationText.placeholder=canObserve?'Escriba una nueva observación...':'No tiene autorización para agregar observaciones a este documento.';observationReadonly.classList.toggle('d-none',canObserve);observationSubmit.classList.add('d-none')};
const syncSubmit=()=>observationSubmit.classList.toggle('d-none',!canObserve||observationText.value.trim()==='');observationText.addEventListener('input',syncSubmit);
const renderHistory=activity=>{const entries=(activity||[]).filter(item=>item.action_type==='observacion_registrada').map(item=>({author:item.user_name||'Usuario',role:item.user_role||'Responsable',date:item.created_at||'',text:item.description||'',action:item.action_type||''}));const box=document.getElementById('mdObservationHistoryBox'),list=document.getElementById('mdObservationHistory'),title=document.getElementById('mdObservationHistoryTitle');if(!entries.length){box.classList.add('d-none');list.innerHTML='';return}box.classList.remove('d-none');title.textContent='Historial de observaciones ('+entries.length+')';list.innerHTML='<div class="observation-timeline">'+entries.map(entry=>'<article class="observation-entry"><div class="observation-entry-header"><span class="observation-avatar"><i class="fa-solid '+(entry.action==='conformidad'?'fa-check':'fa-user')+'"></i></span><div class="observation-author"><strong>'+escapeHtml(entry.author)+'</strong><span>'+escapeHtml(entry.role)+'</span></div><time>'+escapeHtml(entry.date)+'</time></div><p>'+escapeHtml(entry.text)+'</p></article>').join('')+'</div>'};
const openObservation=async id=>{if(!observationModal)return;document.getElementById('mdObservationId').value=id;observationText.value='';setPermission(false);renderHistory([]);observationModal.show();try{const response=await fetch('<?=APP_URL?>/servicios/obtener_observacion_documento_maquinaria.php?id='+encodeURIComponent(id)),data=await response.json();if(!data.ok)throw new Error(data.message||'No se pudo cargar.');const row=data.row,status=row.observation_status||'none';document.getElementById('mdObservationMachine').textContent=row.equipo||'';document.getElementById('mdObservationDocument').textContent=row.documento?'Documento: '+row.documento:'';document.getElementById('mdObservationSeries').textContent=row.serie_placa?'Serie o placa: '+row.serie_placa:'';const box=document.getElementById('mdObservationStatusBox'),badge=document.getElementById('mdObservationStatusBadge');box.classList.toggle('d-none',status==='none');badge.className='badge '+(status==='approved'?'text-bg-success':'text-bg-warning');badge.textContent=status==='approved'?'Conforme':'Observado';document.getElementById('mdObservationStatusDate').textContent=row.observation_at?'Actualizado: '+row.observation_at:'';document.getElementById('mdObservationStatusUser').textContent=row.observation_by?'Última observación por: '+row.observation_by:'';document.getElementById('mdObservationResolvedInfo').textContent=row.observation_resolved_at?'Conforme por: '+(row.resolved_by||'Administrador')+' - '+row.observation_resolved_at:'';setPermission(data.can_observe===true);renderHistory(data.activity||[])}catch(error){observationModal.hide();Swal.fire('Atención',error.message||'No se pudo cargar la observación.','warning')}};
document.querySelectorAll('.md-observation-btn').forEach(button=>button.addEventListener('click',()=>openObservation(button.dataset.id||'')));
observationForm.addEventListener('submit',async event=>{event.preventDefault();if(!canObserve)return;observationSubmit.disabled=true;try{const response=await fetch('<?=APP_URL?>/servicios/guardar_observacion_documento_maquinaria.php',{method:'POST',body:new FormData(observationForm)}),data=await response.json();if(!data.ok)throw new Error(data.message||'No se pudo guardar.');observationModal.hide();location.reload()}catch(error){Swal.fire('Atención',error.message||'No se pudo guardar la observación.','warning')}finally{observationSubmit.disabled=false}});
const pdfElement=document.getElementById('machineDashboardPdfModal'),pdfModal=pdfElement?bootstrap.Modal.getOrCreateInstance(pdfElement):null,pdfFrame=document.getElementById('machineDashboardPdfFrame'),pdfTitle=document.getElementById('machineDashboardPdfTitle');document.querySelectorAll('.dashboard-pdf-preview-btn[data-pdf-url]').forEach(button=>button.addEventListener('click',()=>{pdfTitle.textContent=button.dataset.pdfTitle||'Previsualizar documento';pdfFrame.src=button.dataset.pdfUrl||'';pdfModal.show()}));pdfElement.addEventListener('hidden.bs.modal',()=>pdfFrame.src='');
const initialObservationId=<?=json_encode((string)($_GET['observation_id']??''))?>;if(initialObservationId){const initialButton=document.querySelector('.md-observation-btn[data-id="'+CSS.escape(initialObservationId)+'"]');if(initialButton)setTimeout(()=>{document.getElementById('detalle-maquinaria')?.scrollIntoView({behavior:'smooth'});initialButton.click()},250)}
document.querySelectorAll('.md-approve-btn').forEach(button=>button.addEventListener('click',async()=>{const result=await Swal.fire({title:'¿Marcar conforme?',text:'La fila volverá a su estado visual normal y quedará registrado en el historial.',icon:'question',showCancelButton:true,confirmButtonText:'Sí, conforme',cancelButtonText:'Cancelar'});if(!result.isConfirmed)return;const body=new FormData();body.append('csrf_token','<?=e(csrf_token())?>');body.append('id',button.dataset.id||'');const response=await fetch('<?=APP_URL?>/servicios/marcar_conforme_documento_maquinaria.php',{method:'POST',body}),data=await response.json();if(!data.ok){Swal.fire('Atención',data.message||'No se pudo registrar la conformidad.','warning');return}location.reload()}));if(!window.Chart)return;const d=machineDashboardData,l={position:'bottom',labels:{usePointStyle:true,padding:14}},g='rgba(148,163,184,.16)';Chart.defaults.font.family="'Inter',sans-serif";const centerText={id:'machineCenterText',beforeDraw(chart){const {ctx}=chart;ctx.save();const values=chart.data.datasets[0].data,total=values.reduce((sum,value)=>sum+Number(value||0),0),percent=total?Math.round((Number(values[0]||0)/total)*100):0,meta=chart.getDatasetMeta(0),area=chart.chartArea,x=meta.data[0]?meta.data[0].x:(area?(area.left+area.right)/2:chart.width/2),y=meta.data[0]?meta.data[0].y:(area?(area.top+area.bottom)/2:chart.height/2);ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='bold 34px Inter, sans-serif';ctx.fillStyle='#0f172a';ctx.fillText(percent+'%',x,y-10);ctx.font='bold 11px Inter, sans-serif';ctx.fillStyle='#475569';ctx.fillText('Documentos',x,y+16);ctx.fillText('aptos',x,y+28);ctx.restore()}};
new Chart(mdStatusChart,{type:'doughnut',data:{labels:['APTO','POR VENCER','NO APTO'],datasets:[{data:d.status,backgroundColor:['#198754','#ffc107','#dc3545'],borderColor:'#ffffff',borderWidth:2}]},plugins:[centerText],options:{cutout:'72%',rotation:0,responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{boxWidth:10,boxHeight:10,usePointStyle:true,pointStyle:'rect',padding:16,color:'#1e293b',font:{size:11,weight:'700'},generateLabels(chart){const values=chart.data.datasets[0].data,total=values.reduce((sum,value)=>sum+Number(value||0),0),meta=chart.getDatasetMeta(0);return chart.data.labels.map((label,index)=>{const value=Number(values[index]||0),percent=total?Math.round((value/total)*100):0,style=meta.controller.getStyle(index);return{text:label+': '+percent+'%',fillStyle:style.backgroundColor,strokeStyle:style.backgroundColor,lineWidth:0,hidden:!chart.getDataVisibility(index),index,fontColor:'#1e293b',pointStyle:'rect'}})}}},tooltip:{backgroundColor:'#0f172a',titleColor:'#ffffff',bodyColor:'#ffffff',bodyFont:{weight:'600'},padding:10,cornerRadius:6,callbacks:{label(context){const values=context.dataset.data,total=values.reduce((sum,value)=>sum+Number(value||0),0),value=Number(context.raw||0),percent=total?Math.round((value/total)*100):0;return ' '+context.label+': '+percent+'% ('+value+')'}}}}}});
const companyColors=['#2563eb','#7c3aed','#0ea5e9','#10b981','#f59e0b','#6366f1','#ef4444','#0d9488','#ec4899','#84cc16'];const companyHoverColors=['#1d4ed8','#6d28d9','#0284c7','#059669','#d97706','#4f46e5','#dc2626','#0f766e','#db2777','#65a30d'];const barColors=d.companies.labels.map((_,index)=>companyColors[index%companyColors.length]),barHoverColors=d.companies.labels.map((_,index)=>companyHoverColors[index%companyHoverColors.length]);new Chart(mdCompanyChart,{type:'bar',data:{labels:d.companies.labels,datasets:[{label:'Equipos',data:d.companies.values,backgroundColor:barColors,hoverBackgroundColor:barHoverColors,borderRadius:7,maxBarThickness:64}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{backgroundColor:'#0f172a',padding:10,callbacks:{label(context){const value=Number(context.raw||0);return ' '+value+(value===1?' equipo':' equipos')}}}},scales:{x:{grid:{display:false},ticks:{color:'#334155',font:{weight:'600'}}},y:{beginAtZero:true,ticks:{precision:0,stepSize:1},grid:{color:g}}}}})});</script>
